    internal static void Validate(decimal value, ICollection<string> errors)
    {
        ValidateDecimal(value, 10, 2, errors);
        OnValidate(value, errors);
    }

    /// <summary>ユーザー定義の追加検証（partial・未実装ならゼロコスト）</summary>
