    {
        ExecuteLoad(() =>
        {
            BindingOrderId = _bindingOrderIdSnapshot;
            BindingCustomerId = _bindingCustomerIdSnapshot;
            BindingMemo = _bindingMemoSnapshot;
            BindingAmount = _bindingAmountSnapshot;
            OnCancelEdit();
        });

        RowState = _rowStateSnapshot;
